ALTER TABLE public.traders ADD COLUMN IF NOT EXISTS slug text, ADD COLUMN IF NOT EXISTS biography text, ADD COLUMN IF NOT EXISTS country text, ADD COLUMN IF NOT EXISTS languages text[], ADD COLUMN IF NOT EXISTS experience_years integer, ADD COLUMN IF NOT EXISTS markets text[], ADD COLUMN IF NOT EXISTS instruments text[], ADD COLUMN IF NOT EXISTS trading_style text, ADD COLUMN IF NOT EXISTS strategy_description text, ADD COLUMN IF NOT EXISTS risk_score numeric, ADD COLUMN IF NOT EXISTS win_rate numeric, ADD COLUMN IF NOT EXISTS sharpe_ratio numeric, ADD COLUMN IF NOT EXISTS max_drawdown numeric, ADD COLUMN IF NOT EXISTS monthly_return numeric, ADD COLUMN IF NOT EXISTS minimum_investment numeric, ADD COLUMN IF NOT EXISTS recommended_investment numeric, ADD COLUMN IF NOT EXISTS copy_fee numeric, ADD COLUMN IF NOT EXISTS photo_url text, ADD COLUMN IF NOT EXISTS cover_url text, ADD COLUMN IF NOT EXISTS video_url text, ADD COLUMN IF NOT EXISTS document_url text, ADD COLUMN IF NOT EXISTS gallery_urls text[], ADD COLUMN IF NOT EXISTS tags text[], ADD COLUMN IF NOT EXISTS badges text[], ADD COLUMN IF NOT EXISTS custom_label text, ADD COLUMN IF NOT EXISTS meta_title text, ADD COLUMN IF NOT EXISTS meta_description text, ADD COLUMN IF NOT EXISTS verified boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'active', ADD COLUMN IF NOT EXISTS sort_priority integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS joined_at timestamptz; ALTER TABLE public.traders ADD CONSTRAINT traders_status_valid CHECK (status IN ('active','suspended','archived')); CREATE UNIQUE INDEX IF NOT EXISTS traders_slug_unique ON public.traders(slug) WHERE slug IS NOT NULL; DROP POLICY IF EXISTS traders_public ON public.traders; CREATE POLICY traders_public ON public.traders FOR SELECT TO anon, authenticated USING ((deleted_at IS NULL AND status='active') OR public.is_staff(auth.uid())); CREATE POLICY traders_staff_insert ON public.traders FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid())); CREATE POLICY traders_staff_update ON public.traders FOR UPDATE TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid())); GRANT SELECT ON public.traders TO anon; GRANT SELECT, INSERT, UPDATE ON public.traders TO authenticated; GRANT ALL ON public.traders TO service_role;
CREATE TABLE public.trader_performance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trader_id uuid NOT NULL REFERENCES public.traders(id) ON DELETE CASCADE, period_start date NOT NULL, period_type text NOT NULL CHECK (period_type IN ('daily','weekly','monthly','yearly')), return_pct numeric NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(trader_id,period_start,period_type)); GRANT SELECT ON public.trader_performance TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.trader_performance TO authenticated; GRANT ALL ON public.trader_performance TO service_role; ALTER TABLE public.trader_performance ENABLE ROW LEVEL SECURITY; CREATE POLICY performance_public_read ON public.trader_performance FOR SELECT TO anon,authenticated USING (EXISTS(SELECT 1 FROM public.traders t WHERE t.id=trader_id AND t.deleted_at IS NULL AND t.status='active') OR public.is_staff(auth.uid())); CREATE POLICY performance_staff_insert ON public.trader_performance FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid())); CREATE POLICY performance_staff_update ON public.trader_performance FOR UPDATE TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid())); CREATE POLICY performance_staff_delete ON public.trader_performance FOR DELETE TO authenticated USING (public.is_staff(auth.uid())); CREATE TRIGGER trader_performance_touch BEFORE UPDATE ON public.trader_performance FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.trader_bookmarks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, trader_id uuid NOT NULL REFERENCES public.traders(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,trader_id)); GRANT SELECT,INSERT,DELETE ON public.trader_bookmarks TO authenticated; GRANT ALL ON public.trader_bookmarks TO service_role; ALTER TABLE public.trader_bookmarks ENABLE ROW LEVEL SECURITY; CREATE POLICY bookmarks_own_read ON public.trader_bookmarks FOR SELECT TO authenticated USING (user_id=auth.uid()); CREATE POLICY bookmarks_own_insert ON public.trader_bookmarks FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid()); CREATE POLICY bookmarks_own_delete ON public.trader_bookmarks FOR DELETE TO authenticated USING (user_id=auth.uid()); CREATE TRIGGER trader_bookmarks_touch BEFORE UPDATE ON public.trader_bookmarks FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.marketplace_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), default_view text NOT NULL DEFAULT 'grid' CHECK(default_view IN ('grid','list')), default_sort text NOT NULL DEFAULT 'featured' CHECK(default_sort IN ('featured','roi','followers','risk')), page_size integer NOT NULL DEFAULT 9 CHECK(page_size BETWEEN 3 AND 48), comparison_enabled boolean NOT NULL DEFAULT true, bookmarks_enabled boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.marketplace_settings TO anon; GRANT SELECT,INSERT,UPDATE ON public.marketplace_settings TO authenticated; GRANT ALL ON public.marketplace_settings TO service_role; ALTER TABLE public.marketplace_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY marketplace_settings_read ON public.marketplace_settings FOR SELECT TO anon,authenticated USING (true); CREATE POLICY marketplace_settings_staff_insert ON public.marketplace_settings FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid())); CREATE POLICY marketplace_settings_staff_update ON public.marketplace_settings FOR UPDATE TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid())); CREATE TRIGGER marketplace_settings_touch BEFORE UPDATE ON public.marketplace_settings FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); INSERT INTO public.marketplace_settings(id) VALUES (1) ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.audit_trader_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),CASE WHEN TG_OP='INSERT' THEN 'trader_created' ELSE 'trader_updated' END,'trader',NEW.id,jsonb_build_object('name',NEW.name,'status',NEW.status)); RETURN NEW; END $$; CREATE TRIGGER traders_audit AFTER INSERT OR UPDATE ON public.traders FOR EACH ROW EXECUTE FUNCTION public.audit_trader_change();